import React, { useState, useRef, useEffect } from "react";

/* ---- saved chats live in the browser's localStorage (works on your own site) ---- */
const store = {
  get(key) {
    try {
      const v = localStorage.getItem(key);
      return v ? JSON.parse(v) : null;
    } catch {
      return null;
    }
  },
  set(key, val) {
    try {
      localStorage.setItem(key, JSON.stringify(val));
    } catch {}
  },
};
const slug = (n) =>
  n.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "user";

/* ---- tiny markdown renderer (bold, italic, code, quotes, lists, links) ---- */
function mdInline(text, kp) {
  const nodes = [];
  let k = 0,
    last = 0,
    m;
  const re =
    /(\*\*([^*]+)\*\*)|(`([^`]+)`)|(\*([^*]+)\*)|(_([^_]+)_)|(\[([^\]]+)\]\((https?:\/\/[^\s)]+)\))/g;
  while ((m = re.exec(text))) {
    if (m.index > last) nodes.push(text.slice(last, m.index));
    if (m[1]) nodes.push(<strong key={kp + "b" + k++}>{m[2]}</strong>);
    else if (m[3])
      nodes.push(
        <code key={kp + "c" + k++} className="md-code">
          {m[4]}
        </code>
      );
    else if (m[5]) nodes.push(<em key={kp + "i" + k++}>{m[6]}</em>);
    else if (m[7]) nodes.push(<em key={kp + "u" + k++}>{m[8]}</em>);
    else if (m[9])
      nodes.push(
        <a
          key={kp + "a" + k++}
          href={m[11]}
          target="_blank"
          rel="noopener noreferrer"
          className="md-link"
        >
          {m[10]}
        </a>
      );
    last = m.index + m[0].length;
  }
  if (last < text.length) nodes.push(text.slice(last));
  return nodes;
}

function Markdown({ text }) {
  const lines = String(text).replace(/\r/g, "").split("\n");
  const blocks = [];
  let i = 0,
    key = 0;
  while (i < lines.length) {
    const line = lines[i];
    if (line.trim().startsWith("```")) {
      const code = [];
      i++;
      while (i < lines.length && !lines[i].trim().startsWith("```")) {
        code.push(lines[i]);
        i++;
      }
      i++;
      blocks.push(
        <pre key={key++} className="md-pre">
          <code>{code.join("\n")}</code>
        </pre>
      );
      continue;
    }
    if (line.trim() === "") {
      i++;
      continue;
    }
    const h = line.match(/^(#{1,6})\s+(.*)$/);
    if (h) {
      blocks.push(
        <div key={key++} className={"md-h md-h" + h[1].length}>
          {mdInline(h[2], "h" + key)}
        </div>
      );
      i++;
      continue;
    }
    if (line.trim().startsWith(">")) {
      const q = [];
      while (i < lines.length && lines[i].trim().startsWith(">")) {
        q.push(lines[i].replace(/^\s*>\s?/, ""));
        i++;
      }
      blocks.push(
        <blockquote key={key++} className="md-quote">
          {q.map((x, xi) => (
            <div key={xi}>{mdInline(x, "q" + key + xi)}</div>
          ))}
        </blockquote>
      );
      continue;
    }
    if (/^\s*[-*+]\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*[-*+]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*+]\s+/, ""));
        i++;
      }
      blocks.push(
        <ul key={key++} className="md-ul">
          {items.map((x, xi) => (
            <li key={xi}>{mdInline(x, "l" + key + xi)}</li>
          ))}
        </ul>
      );
      continue;
    }
    if (/^\s*\d+[.)]\s+/.test(line)) {
      const items = [];
      while (i < lines.length && /^\s*\d+[.)]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+[.)]\s+/, ""));
        i++;
      }
      blocks.push(
        <ol key={key++} className="md-ol">
          {items.map((x, xi) => (
            <li key={xi}>{mdInline(x, "o" + key + xi)}</li>
          ))}
        </ol>
      );
      continue;
    }
    const para = [];
    while (
      i < lines.length &&
      lines[i].trim() !== "" &&
      !lines[i].trim().startsWith("```") &&
      !lines[i].trim().startsWith(">") &&
      !/^\s*[-*+]\s+/.test(lines[i]) &&
      !/^\s*\d+[.)]\s+/.test(lines[i]) &&
      !/^#{1,6}\s+/.test(lines[i])
    ) {
      para.push(lines[i]);
      i++;
    }
    blocks.push(
      <p key={key++} className="md-p">
        {para.map((pl, pi) => (
          <React.Fragment key={pi}>
            {pi > 0 && <br />}
            {mdInline(pl, "p" + key + pi)}
          </React.Fragment>
        ))}
      </p>
    );
  }
  return <div className="md">{blocks}</div>;
}
const chatsKey = (name) => `babu-chats-${slug(name)}`;
const uid = () => Math.random().toString(36).slice(2, 10);
const LOGO = "data:image/png;base64,";
const BG = "data:image/jpeg;base64,";

/* ============================== APP ============================== */
export default function App() {
  const [booted, setBooted] = useState(false);
  const [profile, setProfile] = useState(null);
  const [loginName, setLoginName] = useState("");
  const [chats, setChats] = useState([]);
  const [activeId, setActiveId] = useState(null);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [sidebar, setSidebar] = useState(false);
  const [attachment, setAttachment] = useState(null); // { kind:'image'|'pdf', mime, data, name }
  const [textFiles, setTextFiles] = useState([]); // [{ name, text }]
  const [showIntro, setShowIntro] = useState(true);
  const [introExit, setIntroExit] = useState(false);
  const [listening, setListening] = useState(false);

  const scrollRef = useRef(null);
  const inputRef = useRef(null);
  const fileRef = useRef(null);
  const abortRef = useRef(null);
  const recognitionRef = useRef(null);
  const micBaseRef = useRef("");
  const dirty = useRef(false);

  useEffect(() => {
    const name = store.get("babu-profile");
    if (name) {
      setProfile(name);
      const list = store.get(chatsKey(name)) || [];
      setChats(list);
      setActiveId(list[0]?.id ?? null);
    }
    setBooted(true);
  }, []);

  useEffect(() => {
    const t1 = setTimeout(() => setIntroExit(true), 2500);
    const t2 = setTimeout(() => setShowIntro(false), 3100);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, []);

  useEffect(() => {
    if (!booted || !profile || !dirty.current) return;
    store.set(chatsKey(profile), chats);
  }, [chats, profile, booted]);

  useEffect(() => {
    if (scrollRef.current)
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [activeId, chats, loading]);

  const activeChat = chats.find((c) => c.id === activeId) || null;

  function login() {
    const name = loginName.trim();
    if (!name) return;
    store.set("babu-profile", name);
    const list = store.get(chatsKey(name)) || [];
    setProfile(name);
    setChats(list);
    setActiveId(list[0]?.id ?? null);
    setLoginName("");
  }
  function logout() {
    setProfile(null);
    setChats([]);
    setActiveId(null);
    setSidebar(false);
  }

  function newChat() {
    dirty.current = true;
    const c = { id: uid(), title: "New chat", messages: [], updatedAt: Date.now() };
    setChats((cs) => [c, ...cs]);
    setActiveId(c.id);
    setSidebar(false);
    setError(null);
  }
  function selectChat(id) {
    setActiveId(id);
    setSidebar(false);
    setError(null);
  }
  function deleteChat(id, e) {
    e.stopPropagation();
    dirty.current = true;
    setChats((cs) => {
      const left = cs.filter((c) => c.id !== id);
      if (id === activeId) setActiveId(left[0]?.id ?? null);
      return left;
    });
  }

  function updateChat(id, messages) {
    setChats((cs) =>
      cs.map((c) =>
        c.id === id
          ? {
              ...c,
              messages,
              updatedAt: Date.now(),
              title:
                c.title === "New chat" && messages[0]
                  ? messages[0].content.slice(0, 34)
                  : c.title,
            }
          : c
      )
    );
  }

  async function send(text) {
    const typed = (text ?? input).trim();
    const att = attachment;
    const files = textFiles;
    // Need at least some text, a file, or an image/pdf attachment.
    if ((!typed && !att && files.length === 0) || loading) return;
    dirty.current = true;
    setError(null);
    setInput("");
    setAttachment(null);
    setTextFiles([]);

    let chatId = activeId;
    let baseMsgs = activeChat ? activeChat.messages : [];
    if (!activeChat) {
      chatId = uid();
      setChats((cs) => [
        { id: chatId, title: "New chat", messages: [], updatedAt: Date.now() },
        ...cs,
      ]);
      setActiveId(chatId);
      baseMsgs = [];
    }

    // Chips shown on the user's bubble (no heavy data stored).
    const chips = [];
    if (att) chips.push({ kind: att.kind, name: att.name });
    files.forEach((f) => chips.push({ kind: "file", name: f.name }));

    // What we display/store (typed text only) vs. what the model reads.
    const displayContent = typed || (att || files.length ? "" : typed);
    let modelText = typed;
    for (const f of files)
      modelText += `\n\n----- File: ${f.name} -----\n${f.text}`;

    const userMsg = {
      role: "user",
      content: displayContent,
      ...(chips.length ? { attachments: chips } : {}),
    };
    const nextMsgs = [...baseMsgs, userMsg];
    updateChat(chatId, nextMsgs);
    setLoading(true);

    try {
      // Send history as plain text, but swap in the augmented text for the last turn.
      const payloadMsgs = nextMsgs.map((m) => ({
        role: m.role,
        content: m.content,
      }));
      payloadMsgs[payloadMsgs.length - 1] = { role: "user", content: modelText };

      const controller = new AbortController();
      abortRef.current = controller;
      const res = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          messages: payloadMsgs,
          ...(att ? { attachment: { kind: att.kind, mime: att.mime, data: att.data } } : {}),
        }),
        signal: controller.signal,
      });

      const data = await res.json().catch(() => ({}));

      if (!res.ok) {
        const msg =
          (data && data.error
            ? data.error + (data.detail ? " — " + data.detail : "")
            : "") || "Babu couldn't reply. Check the server setup.";
        throw new Error(msg);
      }

      const reply = (data && data.text ? data.text : "").trim();
      updateChat(chatId, [
        ...nextMsgs,
        { role: "assistant", content: reply || "…(no response)" },
      ]);
    } catch (e) {
      if (e.name === "AbortError") {
        // User stopped it — leave their message, add a soft note.
        updateChat(chatId, [
          ...nextMsgs,
          { role: "assistant", content: "_(rok diya)_" },
        ]);
      } else {
        setError(e.message || "Something went wrong. Try again.");
      }
    } finally {
      abortRef.current = null;
      setLoading(false);
      inputRef.current?.focus();
    }
  }

  function stopGenerating() {
    abortRef.current?.abort();
  }

  function toggleMic() {
    const SR =
      typeof window !== "undefined" &&
      (window.SpeechRecognition || window.webkitSpeechRecognition);
    if (!SR) {
      setError("Is browser mein voice input support nahi hai — Chrome try karo.");
      return;
    }
    if (listening) {
      recognitionRef.current && recognitionRef.current.stop();
      return;
    }
    const rec = new SR();
    rec.lang = "en-IN";
    rec.interimResults = true;
    rec.continuous = false;
    micBaseRef.current = input ? input.trim() + " " : "";
    rec.onresult = (e) => {
      let txt = "";
      for (let i = 0; i < e.results.length; i++) txt += e.results[i][0].transcript;
      setInput(micBaseRef.current + txt);
    };
    rec.onerror = () => setListening(false);
    rec.onend = () => {
      setListening(false);
      inputRef.current?.focus();
    };
    recognitionRef.current = rec;
    try {
      rec.start();
      setListening(true);
      setError(null);
    } catch {
      setListening(false);
    }
  }

  /* ---------- file handling ---------- */
  function downscaleImage(file, maxDim = 1024, quality = 0.85) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      const url = URL.createObjectURL(file);
      img.onload = () => {
        const scale = Math.min(1, maxDim / Math.max(img.width, img.height));
        const w = Math.round(img.width * scale);
        const h = Math.round(img.height * scale);
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        canvas.getContext("2d").drawImage(img, 0, 0, w, h);
        URL.revokeObjectURL(url);
        resolve(canvas.toDataURL("image/jpeg", quality).split(",")[1]);
      };
      img.onerror = reject;
      img.src = url;
    });
  }
  function readAsBase64(file) {
    return new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onload = () => resolve(String(r.result).split(",")[1]);
      r.onerror = reject;
      r.readAsDataURL(file);
    });
  }
  function readAsText(file) {
    return new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onload = () => resolve(String(r.result));
      r.onerror = reject;
      r.readAsText(file);
    });
  }

  async function handleFiles(fileList) {
    setError(null);
    for (const file of Array.from(fileList)) {
      const isImage = file.type.startsWith("image/");
      const isPdf =
        file.type === "application/pdf" ||
        file.name.toLowerCase().endsWith(".pdf");
      try {
        if (isImage) {
          const data = await downscaleImage(file);
          setAttachment({ kind: "image", mime: "image/jpeg", data, name: file.name });
        } else if (isPdf) {
          if (file.size > 4 * 1024 * 1024) {
            setError("PDF is too large (max ~4 MB). Try a smaller file.");
            continue;
          }
          const data = await readAsBase64(file);
          setAttachment({
            kind: "pdf",
            mime: "application/pdf",
            data,
            name: file.name,
          });
        } else {
          let txt = await readAsText(file);
          if (txt.length > 200000) txt = txt.slice(0, 200000) + "\n…(truncated)";
          setTextFiles((fs) => [...fs, { name: file.name, text: txt }]);
        }
      } catch {
        setError("Couldn't read " + file.name + ".");
      }
    }
    if (fileRef.current) fileRef.current.value = "";
  }

  function onPaste(e) {
    const items = e.clipboardData?.items || [];
    for (const it of items) {
      if (it.type && it.type.startsWith("image/")) {
        const f = it.getAsFile();
        if (f) {
          e.preventDefault();
          handleFiles([f]);
        }
      }
    }
  }

  function onKeyDown(e) {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      send();
    }
  }

  if (showIntro)
    return (
      <div
        style={S.page}
        className={"intro-wrap" + (introExit ? " intro-exit" : "")}
        onClick={() => setShowIntro(false)}
      >
        <style>{CSS}</style>
        <Aurora />
        <div style={S.introInner}>
          <img src={LOGO} alt="Babu" className="intro-logo" style={S.introLogo} />
          <div className="intro-ring" />
          <div className="intro-name" style={S.introName}>
            Vicky ka Babu
          </div>
          <div className="intro-tag" style={S.introTag}>
            aa gaya tera Babu 😎
          </div>
        </div>
        <div className="intro-skip" style={S.introSkip}>
          tap to skip
        </div>
      </div>
    );

  if (!booted)
    return (
      <div style={S.page}>
        <style>{CSS}</style>
        <Aurora />
        <div style={{ ...S.center, color: "#fff", opacity: 0.85 }}>Loading…</div>
      </div>
    );

  if (!profile)
    return (
      <div style={S.page}>
        <style>{CSS}</style>
        <Aurora />
        <div style={S.loginCard} className="pop-in">
          <img src={LOGO} alt="Babu" style={S.bigMarkImg} />
          <h1 style={S.loginTitle}>Babu</h1>
          <p style={S.loginSub}>
            Enter a name to save your chats and pick up where you left off.
          </p>
          <input
            style={S.loginInput}
            placeholder="Your name"
            value={loginName}
            onChange={(e) => setLoginName(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && login()}
            autoFocus
          />
          <button style={S.loginBtn} onClick={login} disabled={!loginName.trim()}>
            Continue
          </button>
          <p style={S.loginNote}>Saved on this device • no password needed</p>
        </div>
      </div>
    );

  const empty = !activeChat || activeChat.messages.length === 0;
  const lastMsg = activeChat?.messages[activeChat.messages.length - 1];
  const showTyping = loading && (!lastMsg || lastMsg.role === "user");
  const suggestions = [
    "Tu kaun hai?",
    "Roast me a little 🔥",
    "Ek shaayari sunaa",
    "Explain black holes simply",
  ];

  return (
    <div style={S.page}>
      <style>{CSS}</style>
      <Aurora />
      {sidebar && <div style={S.scrim} onClick={() => setSidebar(false)} />}

      <div style={S.shell} className="pop-in shell-glow">
        <aside style={{ ...S.side, transform: sidebar ? "translateX(0)" : "" }} className="side">
          <div style={S.sideHead}>
            <span style={S.sideTitle}>Chats</span>
            <button style={S.newBtn} className="new-btn" onClick={newChat}>+ New</button>
          </div>
          <div style={S.chatList}>
            {chats.length === 0 && <div style={S.sideEmpty}>No saved chats yet.</div>}
            {chats.map((c) => (
              <div
                key={c.id}
                onClick={() => selectChat(c.id)}
                style={{ ...S.chatItem, ...(c.id === activeId ? S.chatItemActive : {}) }}
                className="chat-item"
              >
                <span style={S.chatItemText}>{c.title || "New chat"}</span>
                <button style={S.del} onClick={(e) => deleteChat(c.id, e)} aria-label="Delete">×</button>
              </div>
            ))}
          </div>
          <div style={S.sideFoot}>
            <div style={S.who}>
              <div style={S.whoAvatar}>{profile[0]?.toUpperCase()}</div>
              <span style={S.whoName}>{profile}</span>
            </div>
            <button style={S.logout} onClick={logout}>Log out</button>
          </div>
        </aside>

        <div style={S.main}>
          <header style={S.header}>
            <button className="menu-btn" onClick={() => setSidebar((v) => !v)} aria-label="Menu">
              <span style={S.menuLine} /><span style={S.menuLine} /><span style={S.menuLine} />
            </button>
            <img src={LOGO} alt="Babu" style={S.avatarImg} className="hdr-avatar" />
            <div style={{ lineHeight: 1.15 }}>
              <div style={S.name} className="hdr-name">Babu</div>
              <div style={S.status}><span style={S.statusDot} className="status-dot" /> Vicky ka Babu</div>
            </div>
          </header>

          <main ref={scrollRef} style={S.messages}>
            {empty && (
              <div style={S.welcome} className="fade-in">
                <img src={LOGO} alt="Babu" style={S.bigMarkImg} />
                <h2 style={S.wTitle}>Hello, I'm Babu 😎</h2>
                <p style={S.wSub}>Vicky ka Babu, at your service. Kuch bhi poocho, {profile}.</p>
                <div style={S.chips}>
                  {suggestions.map((s) => (
                    <button key={s} style={S.chip} className="chip" onClick={() => send(s)}>{s}</button>
                  ))}
                </div>
              </div>
            )}

            {activeChat?.messages.map((m, i) => (
              <div
                key={i}
                style={{ ...S.row, justifyContent: m.role === "user" ? "flex-end" : "flex-start" }}
                className="msg-in"
              >
                <div
                  className={"bubble " + (m.role === "user" ? "user-bubble" : "bot-bubble")}
                  style={{ ...S.bubble, ...(m.role === "user" ? S.userB : S.botB) }}
                >
                  {m.attachments && m.attachments.length > 0 && (
                    <div style={S.msgChips}>
                      {m.attachments.map((a, ai) => (
                        <span key={ai} style={S.msgChip}>
                          {a.kind === "image" ? "🖼️" : a.kind === "pdf" ? "📄" : "📎"}{" "}
                          {a.name || a.kind}
                        </span>
                      ))}
                    </div>
                  )}
                  {m.role === "assistant" ? (
                    <Markdown text={m.content} />
                  ) : (
                    m.content
                  )}
                </div>
              </div>
            ))}

            {showTyping && (
              <div style={{ ...S.row, justifyContent: "flex-start" }} className="msg-in">
                <div style={{ ...S.bubble, ...S.botB }}>
                  <span className="typing"><span></span><span></span><span></span></span>
                </div>
              </div>
            )}

            {error && <div style={S.error}>{error}</div>}
          </main>

          <footer style={S.composerWrap}>
            {(attachment || textFiles.length > 0) && (
              <div style={S.pending}>
                {attachment && (
                  <span style={S.pendChip}>
                    {attachment.kind === "image" ? "🖼️" : "📄"} {attachment.name}
                    <button
                      style={S.pendX}
                      onClick={() => setAttachment(null)}
                      aria-label="Remove"
                    >
                      ×
                    </button>
                  </span>
                )}
                {textFiles.map((f, fi) => (
                  <span key={fi} style={S.pendChip}>
                    📎 {f.name}
                    <button
                      style={S.pendX}
                      onClick={() =>
                        setTextFiles((fs) => fs.filter((_, x) => x !== fi))
                      }
                      aria-label="Remove"
                    >
                      ×
                    </button>
                  </span>
                ))}
              </div>
            )}
            <div style={S.composer}>
              <input
                ref={fileRef}
                type="file"
                multiple
                style={{ display: "none" }}
                onChange={(e) => handleFiles(e.target.files)}
              />
              <button
                onClick={() => fileRef.current?.click()}
                style={S.attachBtn}
                className="attach"
                aria-label="Attach file"
                title="Attach image, PDF, or text file"
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                  <path
                    d="M21 11.5l-8.5 8.5a5 5 0 01-7-7l8.5-8.5a3.5 3.5 0 015 5l-8.5 8.5a2 2 0 01-3-3l7.8-7.8"
                    stroke="currentColor"
                    strokeWidth="1.8"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </button>
              <button
                onClick={toggleMic}
                style={{ ...S.attachBtn, ...(listening ? S.micActive : {}) }}
                className={"attach mic-btn" + (listening ? " mic-on" : "")}
                aria-label="Voice input"
                title={listening ? "Sun raha hoon… (tap to stop)" : "Bolke likho"}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                  <rect x="9" y="3" width="6" height="11" rx="3" fill="currentColor" />
                  <path d="M5 11a7 7 0 0014 0M12 18v3" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
                </svg>
              </button>
              <textarea
                ref={inputRef}
                rows={1}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={onKeyDown}
                onPaste={onPaste}
                placeholder="Message Babu…"
                style={S.textarea}
              />
              {loading ? (
                <button
                  onClick={stopGenerating}
                  style={{ ...S.send, ...S.stopBtn }}
                  className="send stop-btn"
                  aria-label="Stop"
                  title="Stop"
                >
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                    <rect x="6" y="6" width="12" height="12" rx="2.5" fill="currentColor" />
                  </svg>
                </button>
              ) : (
                <button
                  onClick={() => send()}
                  disabled={!input.trim() && !attachment && textFiles.length === 0}
                  style={{
                    ...S.send,
                    opacity:
                      !input.trim() && !attachment && textFiles.length === 0 ? 0.4 : 1,
                  }}
                  className="send"
                  aria-label="Send"
                >
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                    <path d="M4 12l16-8-6 8 6 8-16-8z" fill="currentColor" strokeLinejoin="round" />
                  </svg>
                </button>
              )}
            </div>
          </footer>
        </div>
      </div>
    </div>
  );
}

function Aurora() {
  return (
    <div style={S.aurora} aria-hidden>
      <div className="bg-photo" style={{ backgroundImage: `url(${BG})` }} />
      <div className="bg-overlay" />
      <div className="blob b1" /><div className="blob b2" />
    </div>
  );
}

